USE smart_travel_db;
SET NAMES utf8mb4;
START TRANSACTION;
SET @owner=(SELECT member_id FROM members WHERE login_id='user1' AND status='ACTIVE' AND deleted_at IS NULL);
SET @title=(SELECT title FROM course WHERE id=2001 AND member_no=@owner);
SET @region=(SELECT destination FROM course WHERE id=2001 AND member_no=@owner);
SET @start=(SELECT start_date FROM course WHERE id=2001 AND member_no=@owner);
SET @end=(SELECT end_date FROM course WHERE id=2001 AND member_no=@owner);
INSERT INTO lodging(name,address,latitude,longitude,lodging_type,checkin_time,checkout_time,source_provider,source_content_id,status,description) SELECT CONCAT('[테스트] ',@region,' 예약 샘플 숙소'),CONCAT('[TEST] ',@region),37.5665,126.9780,'HOTEL','15:00:00','11:00:00','TEST','MYPAGE-BOOKING-COURSE-2001','APPROVED','Test fixture only; no actual booking or payment' WHERE @title IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lodging WHERE source_provider='TEST' AND source_content_id='MYPAGE-BOOKING-COURSE-2001');
SET @lodging=(SELECT lodging_id FROM lodging WHERE source_provider='TEST' AND source_content_id='MYPAGE-BOOKING-COURSE-2001' LIMIT 1);
INSERT INTO room(lodging_id,name,base_capacity,max_capacity,price_off_weekday,price_off_weekend,description) SELECT @lodging,'[TEST] Standard',2,4,120000,120000,'Test fixture only' WHERE @lodging IS NOT NULL AND NOT EXISTS(SELECT 1 FROM room WHERE lodging_id=@lodging);
SET @room=(SELECT room_id FROM room WHERE lodging_id=@lodging LIMIT 1);
